-- ============================================================================
-- GARMIN TRAINING HUB — MIGRAÇÃO 129: Reformula por completo o módulo
-- "Perfis de Cliente" da trilha (Zona Explorador)
-- ============================================================================
-- Brief completo enviado pelo usuário no chat (2026-09-15): reformular o
-- módulo inteiro, não só limpar emoji (a sql/127, desta mesma sessão, já
-- tinha feito a limpeza pontual — esta migração REESCREVE o conteúdo dela
-- por completo, seguindo a estrutura detalhada de 9 etapas + encerramento
-- do brief).
--
-- Reorganizado em 4 lições (o módulo tinha 3 — mantém o princípio de várias
-- lições focadas, mesmo padrão do resto da Zona Explorador, só que agora com
-- uma lição a mais pra não sobrecarregar nenhuma tela):
-- 1. "Comece pelo cliente" (reaproveita a lição 94bb47ef) — intro do módulo
--    + objetivos + Etapa 1 (lógica do atendimento, timeline) + Etapa 2
--    (o que observar, card_grid de 11 sinais).
-- 2. "Perfis de corrida" (reaproveita 745d31e5) — Etapa 3, accordion com os
--    3 perfis (Iniciante/Dedicado/Performance), cada item com as 5 seções
--    pedidas (quem é/como identificar/o que ouvir/o que perguntar/como
--    conduzir/linhas). Renomeado de "Atleta de Elite/Triatleta" pra "Atleta
--    de Performance" e Forerunner 55→165 como entrada, conforme o brief.
-- 3. "Além da corrida e as perguntas certas" (reaproveita 4e259942) —
--    Etapa 4 (card_grid dos 8 perfis não-corredores, reformatado em
--    quem é/sinais/pergunta inicial/linhas — bem mais enxuto que o texto
--    corrido de antes) + Etapa 5 (5 perguntas em flip_card: frente =
--    pergunta, verso = o que ela revela).
-- 4. "Pratique e domine" (lição NOVA, insert) — Etapa 6 (match_quiz de
--    associação sinal→perfil) + Etapa 7 (cenário da Mariana, cenario_escolha)
--    + Etapa 8 (4 cenários de loja — o 1º com alternativas reais do brief
--    vira cenario_escolha; os outros 3 não têm alternativas erradas
--    fornecidas pelo usuário, só "resposta esperada" aberta, então viram
--    timeline reveal:true em vez de forçar cenario_escolha com distratores
--    inventados) + Etapa 9 (checklist final) + encerramento.
--
-- Todo o texto (perguntas, exemplos de fala, produtos citados) é verbatim
-- do brief do usuário — nenhuma especificação nova foi adicionada. Módulo
-- e as 3 lições reaproveitadas já existiam (sql/030); só a lição 4 é nova.
-- ============================================================================

do $$
declare
  v_module_id uuid := 'abfc3f1d-930c-4e86-995a-2a6738c7242b';
  v_new_lesson_id uuid;
begin
  update modules
     set summary = 'Aprenda a identificar quem está na sua frente antes de apresentar um produto.'
   where id = v_module_id;

  update lessons set title = 'Comece pelo cliente', body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<p>Na Garmin, clientes diferentes procuram soluções diferentes.</p><p>Um corredor pode estar começando agora. Outro pode estar treinando para uma prova. Uma pessoa pode buscar tecnologia para acompanhar sua saúde e rotina. Outra pode procurar um equipamento para uma expedição.</p><p>Por isso, o primeiro passo do atendimento não é apresentar um relógio.</p><p>É entender o cliente.</p>"},{"type":"banner","tone":"info","text":"<strong>Ao final deste módulo, você deverá ser capaz de:</strong><ul><li>Identificar os principais perfis de clientes da loja</li><li>Reconhecer sinais que ajudam a entender cada perfil</li><li>Fazer perguntas que aprofundam a necessidade</li><li>Escolher a linha Garmin mais adequada para começar a apresentação</li><li>Evitar indicar produtos apenas pelo preço ou pela quantidade de recursos</li></ul>"},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Comece pelo perfil, não pelo produto</h3><p>Um cliente nem sempre chega dizendo exatamente o que precisa.</p><p>Ele pode dizer: \"Quero um Garmin para correr.\"</p><p>Isso ainda não é suficiente para indicar um produto.</p><p>Você precisa descobrir:</p><ul><li>Ele está começando ou já treina há anos?</li><li>Corre por saúde ou performance?</li><li>Participa de provas?</li><li>Já usa um relógio GPS?</li><li>O que ele sente falta no equipamento atual?</li></ul><p>Essas respostas mudam completamente a recomendação.</p>"},{"type":"texto_rico","html":"<h4 class=\"cb-model-heading\">A lógica do atendimento</h4>"},{"type":"timeline","items":[{"label":"Pessoa","text":"Quem está na sua frente?"},{"label":"Atividade","text":"O que ela pratica?"},{"label":"Objetivo","text":"O que ela quer alcançar?"},{"label":"Necessidade","text":"O que realmente precisa acompanhar ou melhorar?"},{"label":"Produto","text":"Qual solução faz sentido para esse contexto?"}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Antes de apresentar, observe</h3><p>Preste atenção ao vocabulário, ao contexto e ao comportamento do cliente. A linguagem que ele usa fornece pistas.</p><p><strong>Mas atenção:</strong> o vocabulário é um sinal, não uma conclusão. Sempre confirme através de perguntas.</p>"},{"type":"card_grid","columns":3,"items":[{"title":"Começando a correr","text":"Primeiro contato com corrida ou GPS. Prioriza simplicidade.","tags":[]},{"title":"Performance","text":"Já corre com regularidade e busca evolução e métricas.","tags":[]},{"title":"Triathlon","text":"Treina mais de uma modalidade, alto volume, participa de provas.","tags":[]},{"title":"Outdoor","text":"Trilha, montanha, expedição. Valoriza resistência e navegação.","tags":[]},{"title":"Lifestyle e saúde","text":"Quer acompanhar sono, rotina e bem-estar no dia a dia.","tags":[]},{"title":"Ciclismo","text":"Pedala com frequência, quer GPS e dados no guidão.","tags":[]},{"title":"Natação","text":"Pratica natação ou triathlon, quer métricas na água.","tags":[]},{"title":"Mergulho","text":"Precisa de um computador de mergulho.","tags":[]},{"title":"Golfe","text":"Quer distâncias e recursos de jogo direto no pulso.","tags":[]},{"title":"Motociclismo","text":"Viaja de moto e quer navegação específica.","tags":[]},{"title":"Náutico e pesca","text":"Precisa de sonar ou chartplotter para embarcação.","tags":[]}]}]'::jsonb)
   where id = '94bb47ef-1fd6-4d07-97ff-e5c6b226e47f';

  update lessons set title = 'Perfis de corrida', body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<p>A corrida é uma das principais portas de entrada para a Garmin. Mas nem todo corredor procura a mesma experiência.</p><p>Nesta etapa, você vai aprender a diferenciar três situações comuns na loja.</p>"},{"type":"accordion","items":[{"title":"Corredor Iniciante","html":"<p><strong>Quem é:</strong> Está começando a correr ou retornando ao esporte. Normalmente procura uma experiência simples e quer entender o básico antes de entrar em recursos mais avançados.</p><p><strong>Como identificar:</strong></p><ul><li>Nunca utilizou relógio GPS</li><li>Está começando ou voltando a correr</li><li>Prioriza simplicidade</li><li>Quer acompanhar tempo, distância e evolução</li><li>Ainda não demonstra necessidade de recursos avançados</li></ul><p><strong>O que você pode ouvir:</strong></p><ul><li>\"Estou começando a correr.\"</li><li>\"Quero um relógio para marcar distância.\"</li><li>\"Nunca usei Garmin.\"</li><li>\"Qual é o modelo mais simples?\"</li></ul><p><strong>O que perguntar:</strong></p><ul><li>\"Você já utilizou algum relógio GPS antes?\"</li><li>\"Quantas vezes por semana você pretende correr?\"</li><li>\"O que você gostaria de acompanhar nos seus treinos?\"</li></ul><p><strong>Como conduzir:</strong> Comece pelo objetivo do cliente e explique como a Garmin pode acompanhá-lo desde os primeiros treinos.</p><p><strong>Linhas para conhecer:</strong> Forerunner 165, Forerunner 70, Forerunner 170.</p>"},{"title":"Corredor Dedicado","html":"<p><strong>Quem é:</strong> Já incorporou a corrida à rotina e começa a buscar mais informações para entender desempenho, evolução e treinamento.</p><p><strong>Como identificar:</strong></p><ul><li>Corre com frequência</li><li>Demonstra familiaridade com métricas</li><li>Fala sobre pace, ritmo ou provas</li><li>Já utiliza algum relógio</li><li>Busca evolução e não apenas registro da atividade</li></ul><p><strong>O que você pode ouvir:</strong></p><ul><li>\"Corro três ou quatro vezes por semana.\"</li><li>\"Quero melhorar meu pace.\"</li><li>\"Estou treinando para uma prova.\"</li><li>\"Quero GPS multibanda.\"</li><li>\"Quero acompanhar meu VO2 Max.\"</li></ul><p><strong>O que perguntar:</strong></p><ul><li>\"Você está treinando para alguma prova?\"</li><li>\"O que você gostaria de melhorar no seu desempenho?\"</li><li>\"Você já acompanha suas métricas de treinamento?\"</li><li>\"O que sente falta no seu relógio atual?\"</li></ul><p><strong>Como conduzir:</strong> A conversa começa a sair do simples registro do treino e entra em acompanhamento de performance.</p><p><strong>Linhas para conhecer:</strong> Forerunner 265, Forerunner 570, Forerunner 955.</p>"},{"title":"Atleta de Performance","html":"<p><strong>Quem é:</strong> Tem alto volume de treinamento, participa de provas e procura ferramentas mais completas para acompanhar sua preparação.</p><p><strong>Como identificar:</strong></p><ul><li>Pratica mais de uma modalidade</li><li>Participa de provas</li><li>Já possui experiência com relógios esportivos</li><li>Demonstra conhecimento técnico</li><li>Procura evolução ou upgrade</li><li>Tem necessidades específicas de treinamento</li></ul><p><strong>O que você pode ouvir:</strong></p><ul><li>\"Estou treinando para Ironman.\"</li><li>\"Faço triathlon.\"</li><li>\"Treino todos os dias.\"</li><li>\"Estou buscando um upgrade.\"</li><li>\"Preciso de mais autonomia.\"</li></ul><p><strong>O que perguntar:</strong></p><ul><li>\"Qual é sua principal modalidade hoje?\"</li><li>\"Você está treinando para alguma prova?\"</li><li>\"O que você sente falta no seu relógio atual?\"</li><li>\"Qual informação é mais importante para acompanhar seu treinamento?\"</li></ul><p><strong>Como conduzir:</strong> Aqui, a pergunta deixa de ser apenas \"qual atividade você pratica?\" e passa a ser: \"O que você precisa acompanhar melhor no seu treinamento?\"</p><p><strong>Linhas para conhecer:</strong> Forerunner 970, Forerunner 965, fēnix 8.</p>"}]}]'::jsonb)
   where id = '745d31e5-6b31-411c-bbe0-c7e5b2ef3919';

  update lessons set title = 'Além da corrida e as perguntas certas', body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<p>Você não precisa decorar todo o portfólio de uma vez.</p><p>Primeiro, aprenda a reconhecer qual universo de atividade ou necessidade está na sua frente.</p>"},{"type":"card_grid","columns":2,"items":[{"title":"Aventureiro / Trilheiro","text":"<strong>Quem é:</strong> ama trilhas, camping e expedições, quer resistência e bateria longa.<br><strong>Sinais:</strong> fala de trilha, serra, montanha, expedição.<br><strong>Pergunta inicial:</strong> \"As trilhas que você faz têm sinal de celular?\"<br><strong>Linhas relacionadas:</strong> Instinct 3, fēnix 8, Enduro 3.","tags":[]},{"title":"Lifestyle e Saúde","text":"<strong>Quem é:</strong> quer design elegante com funções inteligentes e acompanhamento de saúde no dia a dia.<br><strong>Sinais:</strong> pede um relógio menor ou mais bonito, compara com Apple Watch, quer acompanhar sono ou ciclo menstrual.<br><strong>Pergunta inicial:</strong> \"É mais pra acompanhar sono, estresse e rotina do dia a dia?\"<br><strong>Linhas relacionadas:</strong> Lily 2, Lily 2 Active, Venu 4.","tags":[]},{"title":"Ciclista","text":"<strong>Quem é:</strong> pedala com frequência, seja estrada, mountain bike ou uso casual.<br><strong>Sinais:</strong> menciona bike, MTB, estrada, gravel, cadência ou potência.<br><strong>Pergunta inicial:</strong> \"Pedala mais na rua, na estrada ou também mountain bike?\"<br><strong>Linhas relacionadas:</strong> Edge 850, Edge 550, Edge 1050, Varia RTL515, Rally RK 200.","tags":[]},{"title":"Nadador / Triatleta","text":"<strong>Quem é:</strong> nada com frequência ou compete em triathlon.<br><strong>Sinais:</strong> fala de piscina, mar, braçadas, SWOLF, triathlon ou duathlon.<br><strong>Pergunta inicial:</strong> \"Já compete em provas de triathlon ou é só treino mesmo?\"<br><strong>Linhas relacionadas:</strong> Forerunner 955, Forerunner 965, fēnix 8, HRM 600.","tags":[]},{"title":"Mergulhador","text":"<strong>Quem é:</strong> precisa de um computador de mergulho.<br><strong>Sinais:</strong> menciona profundidade, NDL, nitrox, mergulho técnico.<br><strong>Pergunta inicial:</strong> \"Pergunta sobre computador de mergulho?\"<br><strong>Linhas relacionadas:</strong> Descent G2, Descent Mk3i, Descent X30.","tags":[]},{"title":"Golfista","text":"<strong>Quem é:</strong> quer distâncias e recursos de jogo direto no pulso.<br><strong>Sinais:</strong> fala de green, par, bunker, handicap.<br><strong>Pergunta inicial:</strong> \"Pergunta por GPS de golfe?\"<br><strong>Linhas relacionadas:</strong> Approach S50, Approach S44.","tags":[]},{"title":"Motociclista","text":"<strong>Quem é:</strong> viaja de moto e quer navegação específica.<br><strong>Sinais:</strong> fala de viagem de moto, rota, estrada.<br><strong>Pergunta inicial:</strong> \"Pergunta por GPS para moto?\"<br><strong>Linhas relacionadas:</strong> Zūmo XT2.","tags":[]},{"title":"Náutico / Pescador","text":"<strong>Quem é:</strong> precisa de sonar ou chartplotter para embarcação.<br><strong>Sinais:</strong> menciona pesca em represa, rio ou mar, barco, canoa, lancha.<br><strong>Pergunta inicial:</strong> \"Fala de barco, canoa, lancha?\"<br><strong>Linhas relacionadas:</strong> Striker Vivid 5cv, Striker 4, ECHOMAP UHD2 52cv.","tags":[]}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>As perguntas que ajudam a encontrar o caminho</h3><p>Quando você ainda não sabe qual produto indicar, não chute. Pergunte.</p><p>Toque em cada pergunta abaixo para ver o que ela ajuda você a descobrir.</p>"},{"type":"flip_card","columns":2,"cards":[{"title":"","subtitle":"","frontText":"\"Qual atividade você pratica?\"","backLabel":"O que descobre","backText":"Ajuda a encontrar o universo de produto."},{"title":"","subtitle":"","frontText":"\"Você já usa algum Garmin ou outro relógio?\"","backLabel":"O que descobre","backText":"Ajuda a entender se estamos diante de uma primeira compra, uma comparação ou uma oportunidade de upgrade."},{"title":"","subtitle":"","frontText":"\"Com que frequência você pratica?\"","backLabel":"O que descobre","backText":"Ajuda a entender o nível de envolvimento."},{"title":"","subtitle":"","frontText":"\"O que você gostaria de acompanhar ou melhorar?\"","backLabel":"O que descobre","backText":"Revela a necessidade."},{"title":"","subtitle":"","frontText":"\"O que é mais importante para você em um novo dispositivo?\"","backLabel":"O que descobre","backText":"Revela o critério de decisão."}]}]'::jsonb)
   where id = '4e259942-be34-46f3-b264-42c681a29e8c';

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Pratique e domine', 'text', 3, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Aqueça o olhar</h3><p>Associe cada sinal do cliente ao perfil correspondente.</p>"},{"type":"match_quiz","pairs":[{"term":"\"Estou começando a correr\"","definition":"Corredor Iniciante"},{"term":"\"Quero melhorar meu pace e estou treinando para uma prova\"","definition":"Corredor Dedicado"},{"term":"\"Estou treinando para Ironman\"","definition":"Atleta de Performance"},{"term":"\"Quero um relógio para acompanhar sono e saúde no dia a dia\"","definition":"Lifestyle e Saúde"},{"term":"\"Preciso de navegação para minhas trilhas\"","definition":"Aventureiro / Trilheiro"},{"term":"\"Quero GPS para usar na minha bike\"","definition":"Ciclista"}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Um cliente pode ter mais de um perfil</h3><p>Um mesmo cliente pode pertencer a mais de um universo: corredor e triatleta, corredor e outdoor, ciclista e outdoor, lifestyle e corrida.</p><p>Por isso, não tente colocar o cliente em uma única caixa. O perfil serve para orientar a conversa, não para limitar a recomendação.</p>"},{"type":"cenario_escolha","context":"Mariana entra na loja dizendo que corre três vezes por semana, faz trilhas aos finais de semana e quer trocar seu relógio atual por um modelo mais completo.","prompt":"Qual é a melhor forma de conduzir esse atendimento?","options":[{"text":"Considerar apenas o perfil de corrida, porque foi a primeira atividade mencionada.","correct":false,"feedback":"Mariana apresenta mais de um perfil. O papel do vendedor é entender qual necessidade tem maior peso na decisão antes de restringir a recomendação."},{"text":"Mostrar imediatamente o produto mais completo.","correct":false,"feedback":"Mariana apresenta mais de um perfil. O papel do vendedor é entender qual necessidade tem maior peso na decisão antes de restringir a recomendação."},{"text":"Explorar quais atividades e necessidades têm maior importância para ela antes de recomendar.","correct":true,"feedback":"Mariana apresenta mais de um perfil. O papel do vendedor é entender qual necessidade tem maior peso na decisão antes de restringir a recomendação."},{"text":"Apresentar todos os relógios que atendem corrida e outdoor.","correct":false,"feedback":"Mariana apresenta mais de um perfil. O papel do vendedor é entender qual necessidade tem maior peso na decisão antes de restringir a recomendação."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Situações reais de loja</h3><p>Agora é com você.</p>"},{"type":"cenario_escolha","context":"Cliente: \"Quero um Garmin para começar a correr.\"","prompt":"Qual deve ser sua primeira reação?","options":[{"text":"Mostrar o modelo mais vendido.","correct":false,"feedback":"Antes de recomendar, entenda o nível de experiência e a necessidade."},{"text":"Perguntar se ele já utiliza algum relógio e o que deseja acompanhar.","correct":true,"feedback":"Antes de recomendar, entenda o nível de experiência e a necessidade."},{"text":"Mostrar imediatamente três Forerunner.","correct":false,"feedback":"Antes de recomendar, entenda o nível de experiência e a necessidade."},{"text":"Perguntar qual é o orçamento.","correct":false,"feedback":"Antes de recomendar, entenda o nível de experiência e a necessidade."}]},{"type":"texto_rico","html":"<p>Cliente: \"Já tenho um relógio, corro quatro vezes por semana e estou treinando para uma meia maratona.\"</p>"},{"type":"timeline","reveal":true,"items":[{"label":"O que você precisa descobrir antes de recomendar um upgrade?","text":"O que ele sente falta no relógio atual e o que deseja melhorar no treinamento."}]},{"type":"texto_rico","html":"<p>Cliente: \"Faço trilha, viajo bastante e quero algo resistente para usar nas minhas aventuras.\"</p>"},{"type":"timeline","reveal":true,"items":[{"label":"Qual universo deve orientar sua investigação?","text":"Outdoor."},{"label":"Qual informação você ainda precisa descobrir antes de apresentar um produto?","text":"Necessidade de navegação, autonomia, resistência, tipo de uso e contexto da aventura."}]},{"type":"texto_rico","html":"<p>Cliente: \"Quero um relógio bonito para usar no trabalho, mas também quero acompanhar meu sono e minha saúde.\"</p>"},{"type":"timeline","reveal":true,"items":[{"label":"Qual abordagem faz mais sentido?","text":"Investigar rotina, prioridades de saúde e preferência de uso antes de apresentar uma linha lifestyle."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Estou pronto para atender?</h3>"},{"type":"checklist","items":["Consigo identificar os principais universos de produtos Garmin.","Consigo diferenciar um cliente iniciante de um cliente experiente.","Consigo reconhecer sinais no vocabulário do cliente.","Sei perguntar qual atividade o cliente pratica.","Sei descobrir o objetivo principal.","Sei identificar se ele já possui um dispositivo.","Sei entender o que ele gostaria de melhorar.","Consigo escolher uma linha Garmin para começar a conversa.","Não apresento vários produtos antes de entender a necessidade.","Consigo explicar por que determinado produto faz sentido para aquele cliente.","Sei que um cliente pode ter mais de um perfil.","Sei que perfil é um ponto de partida e não uma conclusão."],"reflection":"Você não precisa decorar o portfólio inteiro no primeiro dia. Primeiro, aprenda a ler o cliente. Depois, entenda a necessidade. Então, conecte essa necessidade ao universo Garmin correto. Produto é consequência de uma boa sondagem."},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>O principal aprendizado</h3><p>Um bom atendimento Garmin começa antes da apresentação do produto.</p><p>Você não precisa saber todas as respostas imediatamente. Precisa saber o que perguntar.</p>"},{"type":"texto_rico","html":"<p class=\"cb-model-heading\"><strong>OUÇA → PERGUNTE → ENTENDA → DIRECIONE → APRESENTE</strong></p>"},{"type":"banner","tone":"success","text":"Quem entende o cliente consegue indicar melhor o produto."}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a 4ª lição do módulo Perfis de Cliente.';
  end if;
end $$;

-- ============================================================================
-- FIM DA MIGRAÇÃO 129
-- ============================================================================
